def time_to_minutes(time_str):
    hours, minutes = map(int, time_str.split(':'))
    return hours * 60 + minutes

def minutes_to_time(minutes):
    hours = minutes // 60
    minutes = minutes % 60
    return f"{hours:02d}:{minutes:02d}"

def get_free_intervals(busy_intervals, work_start, work_end):
    free = []
    current = work_start
    for start, end in sorted(busy_intervals):
        if current < start:
            free.append((current, start))
        current = max(current, end)
    if current < work_end:
        free.append((current, work_end))
    return free

def find_meeting_time(patricia_busy, jesse_busy, work_start, work_end, duration):
    patricia_free = get_free_intervals(patricia_busy, work_start, work_end)
    jesse_free = get_free_intervals(jesse_busy, work_start, work_end)

    i = j = 0
    while i < len(patricia_free) and j < len(jesse_free):
        start = max(patricia_free[i][0], jesse_free[j][0])
        end = min(patricia_free[i][1], jesse_free[j][1])
        if end - start >= duration:
            return start, start + duration
        if patricia_free[i][1] < jesse_free[j][1]:
            i += 1
        else:
            j += 1
    return None

def main():
    work_start = time_to_minutes("09:00")
